75	
76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /** Maximum number of owners a single city may contain; creating an owner in a city that
82	     *  already has this many owners is rejected with 409 Conflict. */
83	    private static final int MAX_OWNERS_PER_CITY = 50;
84	
85	    /** When the owner's city already contains at least this many owners (but fewer than
86	     *  {@link #MAX_OWNERS_PER_CITY}, so the create is still allowed), the new owner's
87	     *  'capacityWarning' flag is set true to signal the city is approaching its capacity limit;
88	     *  otherwise it is false. */
89	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
90	
91	    /** Maximum number of owners that may be created on a single day (by registration date); creating
92	     *  an owner once this many owners already carry today's registration date is rejected with
93	     *  429 Too Many Requests. */
94	    private static final int MAX_OWNERS_PER_DAY = 100;
95	
96	    /** When more than this many owners already carry today's registration date at creation time, the
97	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
98	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
99	
100	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
101	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
102	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
103	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
104	
105	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
106	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
107	
108	    /** Serializes the immutable structured audit event emitted alongside the audit line. */
109	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
110	
111	    /** Monotonically increasing sequence stamped on each structured {@code OWNER_CREATED} event,
112	     *  shared across all creates so the events carry a strict global order. */
113	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
114	
115	    private final ClinicService clinicService;
116	
117	    private final OwnerMapper ownerMapper;
118	
119	    private final PetMapper petMapper;
120	
121	    private final VisitMapper visitMapper;
122	
123	    private final TelephoneNormalizer telephoneNormalizer;
124	
125	    private final HouseholdNormalizer householdNormalizer;
126	
127	    private final AddressNormalizer addressNormalizer;
128	
129	    private final EmailNormalizer emailNormalizer;
130	
131	    /**
132	     * Records the owner created for each already-seen {@code Idempotency-Key}, so a create that
133	     * repeats with the same key returns the originally created owner (200) instead of creating a
134	     * duplicate. Keyed by the header value; concurrent because creates may be handled on any thread.
135	     */
136	    private final java.util.concurrent.ConcurrentMap<String, OwnerDto> idempotentCreates =
137	        new java.util.concurrent.ConcurrentHashMap<>();
138	
139	    public OwnerRestControllerV1(ClinicService clinicService,
140	                                 OwnerMapper ownerMapper,
141	                                 PetMapper petMapper,
142	                                 VisitMapper visitMapper,
143	                                 TelephoneNormalizer telephoneNormalizer,
144	                                 HouseholdNormalizer householdNormalizer,
145	                                 AddressNormalizer addressNormalizer,
146	                                 EmailNormalizer emailNormalizer) {
147	        this.clinicService = clinicService;
148	        this.ownerMapper = ownerMapper;
149	        this.petMapper = petMapper;
150	        this.visitMapper = visitMapper;
151	        this.telephoneNormalizer = telephoneNormalizer;
152	        this.householdNormalizer = householdNormalizer;
153	        this.addressNormalizer = addressNormalizer;
154	        this.emailNormalizer = emailNormalizer;
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
160	        Collection<Owner> owners;
161	        if (lastName != null) {
162	            owners = this.clinicService.findOwnerByLastName(lastName);
163	        } else {
164	            owners = this.clinicService.findAllOwners();
165	        }
166	        if (owners.isEmpty()) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
185	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
186	        // been used for a successful create, return the originally created owner with 200 OK instead
187	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
188	        // with 409). A first, unseen key runs the normal create and records its result under the key.
189	        String idempotencyKey = currentIdempotencyKey();
190	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
191	            return createOwner(ownerFieldsDto);
192	        }
193	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
194	        if (previouslyCreated != null) {
195	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
196	        }
197	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
198	        idempotentCreates.put(idempotencyKey, response.getBody());
199	        return response;
200	    }
201	
202	    /**
203	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
204	     * the request carries no such header (or there is no active servlet request). Reading it from the
205	     * request context here keeps the header — a request-level concern surrounding the create — out of
206	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
207	     *
208	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
209	     */
210	    private String currentIdempotencyKey() {
211	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
212	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
213	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
214	        }
215	        return null;
216	    }
217	
218	    /**
219	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
220	     * response for the newly persisted owner: the request fields are mapped and normalized, every
221	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
222	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
223	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
224	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
225	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
226	     * {@code addOwner} without disturbing the creation steps gathered here.
227	     *
228	     * @param ownerFieldsDto the submitted owner fields
229	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
230	     */
231	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
232	        HttpHeaders headers = new HttpHeaders();
233	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
234	        normalizeOwnerFields(owner);
235	        // Enforce the pre-persistence policies that can reject the new owner outright.
236	        rejectDisallowedOwnerCreation(owner);
237	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
238	        // function of last name and postcode), cap the membership level for a new household member,
239	        // and record the household size. The household id is no longer part of the identity key, so
240	        // this no longer rejects a household duplicate: owners sharing a household are distinguished
241	        // by the identity-key check below and otherwise flagged as soft duplicates.
242	        boolean declaredHouseholdMember =
243	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
244	        // Reject the create when the owner's whole derived identity key (the SHA-256 over normalized
245	        // telephone, lower-cased email and the Soundex of the last name) already matches an existing
246	        // owner. This single rule subsumes the former separate telephone, email and household
247	        // duplicate checks.
248	        rejectWhenIdentityInUse(owner);
249	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
250	        // shares an existing owner's last name and postcode with a different telephone. A declared
251	        // household member is never flagged: it is a known member, not a suspected duplicate.
252	        assignPossibleDuplicate(owner, declaredHouseholdMember);
253	        // Assign the remaining create-time derived fields (namesake count, customer code,
254	        // membership number and bulk-signup warning), each fixed at creation time.
255	        assignDerivedFields(owner);
256	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
257	        // derived fields above because the level is computed from the membership points, which depend
258	        // on the namesake count assigned in assignDerivedFields.
259	        assignMembershipLevel(owner);
260	        this.clinicService.saveOwner(owner);
261	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
262	        // Record the successful create on the dedicated AUDIT log.
263	        auditOwnerCreated(owner, ownerDto);
264	        headers.setLocation(UriComponentsBuilder.newInstance()
265	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
266	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
267	    }
268	
269	    /**
270	     * Emits the audit line recording a successful owner create on the dedicated {@code AUDIT} log,
271	     * carrying the owner id, its current primary identifier (see {@link #primaryIdentifier}), the
272	     * registration date, membership level and membership number so the create can be traced. Keeping
273	     * the audit emission in its own helper leaves {@link #createOwner} a thin pipeline and gives the
274	     * create's audit side-effects a single home, so a further audit side-effect of a create is added
275	     * here (or as a sibling helper) rather than inline in the pipeline.
276	     *
277	     * @param owner    the persisted owner
278	     * @param ownerDto the mapped view of the persisted owner, source of the membership fields
279	     */
280	    private void auditOwnerCreated(Owner owner, OwnerDto ownerDto) {
281	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
282	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
283	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
284	        auditOwnerCreatedEvent(owner, ownerDto);
285	    }
286	
287	    /**
288	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} log as a JSON
289	     * object {@code {seq, ownerId, customerCode, membershipLevel, event}}. The {@code seq} is a
290	     * strictly increasing integer across every create (see {@link #OWNER_CREATED_SEQUENCE}), giving
291	     * the events a total order. The identifier field carries the owner's current primary identifier
292	     * (see {@link #primaryIdentifier}) — the customer code today, and whatever replaces it later — so
293	     * unifying the customer code into a member id makes the event carry the member id by changing only
294	     * {@link #primaryIdentifier}.
295	     *
296	     * @param owner    the persisted owner
297	     * @param ownerDto the mapped view of the persisted owner, source of the membership level
298	     */
299	    private void auditOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
300	        OwnerCreatedEvent event = new OwnerCreatedEvent(
301	            OWNER_CREATED_SEQUENCE.incrementAndGet(), owner.getId(), primaryIdentifier(owner),
302	            ownerDto.getMembershipLevel(), "OWNER_CREATED");
303	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
304	    }
305	
306	    /**
307	     * The immutable structured audit event published for a successful owner create. Its
308	     * {@code customerCode} field carries the owner's current primary identifier (see
309	     * {@link #primaryIdentifier}), so the same event shape follows the identifier as it changes.
310	     */
311	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
312	        Integer membershipLevel, String event) {
313	    }
314	
315	    /**
316	     * Returns the owner's current primary identifier: the single value that identifies the owner in
317	     * the audit trail and in any audit side-effect of a create. This is the customer code today;
318	     * resolving it through one accessor means that if the primary identifier is later changed (for
319	     * example, the customer code being unified into a member id) every audit consumer follows the new
320	     * identifier by changing only this method.
321	     *
322	     * @param owner the owner whose primary identifier is required
323	     * @return the owner's current primary identifier
324	     */
325	    private String primaryIdentifier(Owner owner) {
326	        return owner.getCustomerCode();
327	    }
328	
329	    /**
330	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
331	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
332	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
333	     * the sequence of create-time rejections stays readable and a new rule is added as one more
334	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
335	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
336	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}.
337	     *
338	     * @param owner the newly mapped and normalized owner being created
339	     */
340	    private void rejectDisallowedOwnerCreation(Owner owner) {
341	        rejectWhenDailyLimitReached(owner);
342	        rejectWhenCityAtCapacity(owner);
343	    }
344	
345	    /**
346	     * Applies the household-membership rules for a newly normalized owner being created. The
347	     * household id is a deterministic function of the owner's last name and postcode, so owners
348	     * with the same last name and postcode share it automatically; it is assigned to the new owner
349	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
350	     * same last name and postcode is a member of the same household. A new owner may join an
351	     * existing household: rather than the create being rejected, the newcomer's membership level is
352	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
353	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
354	     * declared member and is never flagged as a possible duplicate. The owner's
355	     * {@code householdSize} (the number of owners sharing the household after this create) is
356	     * recorded either way.
357	     *
358	     * @param owner           the newly mapped and normalized owner being created
359	     * @param sharesHousehold whether the request declared that the owner shares an existing household
360	     * @return {@code true} if the owner joined an existing household as a declared member
361	     */
362	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
363	        // Assign the deterministic household id (a pure function of last name and postcode) so every
364	        // owner with the same last name and postcode shares it automatically.
365	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
366	        // Identify any existing owners in the same household (same computed household id). A new owner
367	        // may join an existing household: its membership level is capped at one above the household's
368	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
369	        List<Owner> householdMembers = sameHouseholdOwners(owner);
370	        // An owner that joins an existing household while the request declares it shares that
371	        // household is a known, declared member and so is never flagged as a possible duplicate.
372	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
373	        // Record the size of this owner's household after this create, fixed at creation time.
374	        owner.setHouseholdSize(householdMembers.size() + 1);
375	        return declaredHouseholdMember;
376	    }
377	
378	    /**
379	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
380	     * has already been resolved: the namesake count, the per-city customer code, the membership
381	     * number derived from that customer code and the registration fiscal year, the bulk-signup warning
382	     * flag and the city capacity warning flag. Each value is fixed at creation time and is
383	     * independent of the others. Grouping them
384	     * here keeps {@link #addOwner} focused on the high-level create sequence.
385	     *
386	     * @param owner the owner being created, already normalized and with its household resolved
387	     */
388	    private void assignDerivedFields(Owner owner) {
389	        // Record how many existing owners already share this owner's first and last name
390	        // (compared case-insensitively) before this create, fixed at creation time.
391	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
392	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
393	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
394	        // time.
395	        owner.setCustomerCode(customerCode(owner));
396	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
397	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
398	        // creation time.
399	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
400	        // Flag the create when more than 80 owners have already been created on this owner's
401	        // (adjusted business-day) registration date, fixed at creation time.
402	        owner.setBulkSignupWarning(
403	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
404	        // Flag the create when the owner's city is approaching its capacity limit: it already holds
405	        // between CAPACITY_WARNING_THRESHOLD and MAX_OWNERS_PER_CITY - 1 owners (40-49). A city at or
406	        // over the limit is rejected earlier (see rejectWhenCityAtCapacity), so this is never reached
407	        // for a full city. Fixed at creation time.
408	        int cityOwners = countOwnersInCity(owner.getCity());
409	        owner.setCapacityWarning(
410	            cityOwners >= CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
411	    }
412	
413	    /**
414	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
415	     * time. The level a newly created owner would earn from their membership points cannot exceed
416	     * one above the current maximum membership level among their existing household members (the
417	     * owners already sharing this owner's household id); the capped value is stored so it is returned
418	     * unchanged on later reads. When the owner has no existing household member no cap applies and
419	     * the plain points-derived level is used.
420	     *
421	     * @param owner the owner being created, already normalized and with its derived fields assigned
422	     */
423	    private void assignMembershipLevel(Owner owner) {
424	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
425	        List<Owner> householdMembers = sameHouseholdOwners(owner);
426	        if (!householdMembers.isEmpty()) {
427	            int maxMemberLevel = householdMembers.stream()
428	                .mapToInt(this::memberLevel)
429	                .max()
430	                .getAsInt();
431	            level = Math.min(level, maxMemberLevel + 1);
432	        }
433	        owner.setMembershipLevel(level);
434	    }
435	
436	    /**
437	     * Returns an existing household member's membership level for the purpose of capping a new
438	     * member's level: the level stored on the member when present (the already-capped value fixed at
439	     * its own creation), otherwise the level derived from its membership points (for members created
440	     * before the level was persisted).
441	     *
442	     * @param member an existing owner in the same household
443	     * @return the member's membership level
444	     */
445	    private int memberLevel(Owner member) {
446	        return member.getMembershipLevel() != null
447	            ? member.getMembershipLevel()
448	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
449	    }
450	
451	    /**
452	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
453	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) is the SHA-256 hex over
454	     * the normalized telephone, the lower-cased email (or empty) and the Soundex of the last name, so
455	     * this single rule replaces the former separate telephone, email and household duplicate checks:
456	     * two owners collide only when their whole keys are equal, and members of one household with
457	     * different telephones have different keys and are both allowed (instead flagged as soft
458	     * duplicates).
459	     *
460	     * @param owner the owner being created, already normalized
461	     */
462	    private void rejectWhenIdentityInUse(Owner owner) {
463	        String identityKey = owner.getIdentityKey();
464	        boolean inUse = existingOwners()
465	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
466	        if (inUse) {
467	            throw new DuplicateIdentityException(
468	                "An owner with identity key " + identityKey + " already exists");
469	        }
470	    }
471	
472	    /**
473	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
474	     * duplicate (identity-key) check. When an existing owner has a different identity key but shares
475	     * this owner's postcode and the Soundex code of its last name, the new owner is still created but
476	     * flagged as a possible duplicate: {@code possibleDuplicate} is set true and
477	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
478	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
479	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
480	     * possible duplicate. A declared household member is never flagged: it is a known member of the
481	     * household, not a suspected duplicate. Both values are fixed at creation time.
482	     *
483	     * @param owner                   the owner being created, already normalized and confirmed not a
484	     *                                hard duplicate
485	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
486	     *                                member
487	     */
488	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
489	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
490	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
491	            .map(Owner::getId)
492	            .min(Integer::compareTo)
493	            .orElse(null);
494	        owner.setPossibleDuplicate(matchId != null);
495	        owner.setPossibleDuplicateOf(matchId);
496	    }
497	
498	    /**
499	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
500	     * two have different identity keys (an equal key would already have been rejected as a hard
501	     * duplicate) but share a postcode (required on both sides, so an owner without a postcode never
502	     * matches) and the Soundex code of their last name. A match flags the new owner as a possible
503	     * duplicate of the existing one without rejecting the create.
504	     *
505	     * @param existing an existing owner to compare against
506	     * @param owner    the owner being created
507	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
508	     */
509	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
510	        return existing.getPostcode() != null
511	            && existing.getPostcode().equals(owner.getPostcode())
512	            && Soundex.encode(existing.getLastName()).equals(Soundex.encode(owner.getLastName()))
513	            && !existing.getIdentityKey().equals(owner.getIdentityKey());
514	    }
515	
516	    /**
517	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
518	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
519	     *
520	     * @param owner the owner being created
521	     */
522	    private void rejectWhenDailyLimitReached(Owner owner) {
523	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
524	            throw new DailyOwnerLimitExceededException(
525	                "The maximum number of owners that may be created today has already been reached");
526	        }
527	    }
528	
529	    /**
530	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
531	     * or more owners, with 409 Conflict.
532	     *
533	     * @param owner the owner being created
534	     */
535	    private void rejectWhenCityAtCapacity(Owner owner) {
536	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
537	            throw new CityCapacityExceededException(
538	                "The city " + owner.getCity() + " already contains the maximum number of owners");
539	        }
540	    }
541	
542	    /**
543	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
544	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
545	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
546	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
547	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
548	     * server's current date. Canonicalising the address here, before the household checks read it,
549	     * ensures duplicate detection and the shared household id both compare the normalized form.
550	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
551	     * duplicate, household and customer-code rules.
552	     *
553	     * @param owner the newly mapped owner to canonicalize
554	     */
555	    private void normalizeOwnerFields(Owner owner) {
556	        // Canonicalize the owner's address fields on create so the address is stored and returned in
557	        // canonical form and every later comparison (household duplicate detection and the shared
558	        // household id) uses it. A value that is blank after normalization is rejected with 400.
559	        normalizeAddressFields(owner);
560	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
561	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
562	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
563	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
564	        // Store the (already syntactically validated) email lower-cased so it is persisted and
565	        // returned in canonical form. A missing email is left untouched.
566	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
567	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
568	        // canonicalization so the comparison sees the lower-cased value.
569	        rejectDisposableEmailDomain(owner.getEmail());
570	        // Validate the optional postcode against the fixed range for the city's region. A postcode
571	        // is checked only when present (it is optional); one out of range for the city's region is
572	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
573	        // value is left unchanged.
574	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
575	        // Reject a supplied registration date that is later than the server's current date with
576	        // 400, before any defaulting or business-day adjustment, so a future date is never
577	        // persisted regardless of how the roll-forward would move it.
578	        rejectFutureRegistrationDate(owner.getRegistrationDate());
579	        // Default the registration date to the server's current date when the client did not
580	        // supply one, then roll the effective date forward to a business day so a Saturday or
581	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
582	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
583	        // date-derived field (such as the membership number's year segment) and the per-day
584	        // create-limit are computed from.
585	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
586	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
587	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
588	    }
589	
590	    /**
591	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
592	     * returned in canonical form. The owner may supply its address in either of two forms and the
593	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
594	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
595	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
596	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
597	     * stored {@code address} is composed from the normalized structured lines when present — the
598	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
599	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
600	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
601	     * here, before the household checks read it, ensures duplicate detection and the shared household
602	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
603	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
604	     *
605	     * @param owner the newly mapped owner whose address is canonicalized
606	     */
607	    private void normalizeAddressFields(Owner owner) {
608	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
609	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
610	            owner.setAddressLine1(line1);
611	            String composed = line1;
612	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
613	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
614	                owner.setAddressLine2(line2);
615	                composed = line1 + " " + line2;
616	            }
617	            owner.setAddress(composed);
618	        }
619	        else {
620	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
621	        }
622	    }
623	
624	    /**
625	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
626	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
627	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
628	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
629	     * domain part is left untouched.
630	     *
631	     * @param email the owner's canonicalized email, or {@code null} when absent
632	     */
633	    private void rejectDisposableEmailDomain(String email) {
634	        if (email == null) {
635	            return;
636	        }
637	        int at = email.lastIndexOf('@');
638	        if (at < 0) {
639	            return;
640	        }
641	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
642	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
643	            throw new DisposableEmailException(
644	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
645	        }
646	    }
647	
648	    /**
649	     * Rejects a supplied registration date that is later than the server's current date with a
650	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
651	     * accepted, and a date on or before today is left for the normal defaulting and business-day
652	     * adjustment.
653	     *
654	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
655	     */
656	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
657	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
658	            throw new InvalidRegistrationDateException(
659	                "The supplied registration date " + registrationDate + " is later than the current date");
660	        }
661	    }
662	
663	    /**
664	     * The fixed list of public holidays. A registration date that lands on one of these dates is
665	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
666	     */
667	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
668	        java.time.LocalDate.of(2026, 1, 1),
669	        java.time.LocalDate.of(2026, 1, 26),
670	        java.time.LocalDate.of(2026, 4, 25),
671	        java.time.LocalDate.of(2026, 12, 25),
672	        java.time.LocalDate.of(2026, 12, 28));
673	
674	    /**
675	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
676	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
677	     * unchanged. Applied to the effective registration date (whether supplied in the request or
678	     * defaulted to the server date) so the persisted registration date, every value derived from it
679	     * and the per-day create-limit all use the adjusted business day.
680	     *
681	     * @param date the effective registration date
682	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
683	     */
684	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
685	        java.time.LocalDate adjusted = date;
686	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
687	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
688	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
689	            adjusted = adjusted.plusDays(1);
690	        }
691	        return adjusted;
692	    }
693	
694	    /**
695	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
696	     * region derived from the owner's postcode (falling back to the city, via
697	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
698	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
699	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
700	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
701	     * distinct customer codes.
702	     *
703	     * @param owner the owner being created, already normalized
704	     * @return the formatted, de-duplicated customer code
705	     */
706	    private String customerCode(Owner owner) {
707	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
708	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
709	        String base = region + "-" + hash8;
710	        Set<String> taken = existingOwners()
711	            .map(Owner::getCustomerCode)
712	            .filter(code -> code != null)
713	            .collect(Collectors.toSet());
714	        if (!taken.contains(base)) {
715	            return base;
716	        }
717	        int n = 2;
718	        while (taken.contains(base + "-" + n)) {
719	            n++;
720	        }
721	        return base + "-" + n;
722	    }
723	
724	    /**
725	     * Streams the existing owners that the create-time rules match a new owner against. Every
726	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
727	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
728	     * own matching criterion rather than on how the existing owners are retrieved.
729	     *
730	     * @return a stream over all existing owners
731	     */
732	    private Stream<Owner> existingOwners() {
733	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
734	        // new create, so the duplicate, identity and household checks (and the other create-time
735	        // scans built on this helper) ignore it.
736	        return this.clinicService.findAllOwners().stream()
737	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
738	    }
739	
740	    /**
741	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
742	     * fix the per-city sequence of an owner's customer code at creation time.
743	     *
744	     * @param city the city of the owner being created
745	     * @return the number of existing owners in a matching city
746	     */
747	    private int countOwnersInCity(String city) {
748	        return (int) existingOwners()
749	            .filter(existing -> existing.getCity() != null
750	                && existing.getCity().equalsIgnoreCase(city))
751	            .count();
752	    }
753	
754	    /**
755	     * Counts the existing owners whose registration date is the given adjusted business day. Used
756	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
757	     * owners already carry that business day as their registration date.
758	     *
759	     * @param date the adjusted business-day registration date to match
760	     * @return the number of existing owners registered on that date
761	     */
762	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
763	        return (int) existingOwners()
764	            .filter(existing -> date.equals(existing.getRegistrationDate()))
765	            .count();
766	    }
767	
768	    /**
769	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
770	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
771	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
772	     * after 1 July carries the following calendar year's fiscal year.
773	     *
774	     * @param customerCode     the owner's customer code
775	     * @param registrationDate the owner's registration date
776	     * @return the formatted membership number
777	     */
778	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
779	        return String.format("%s-M%02d",
780	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
781	    }
782	
783	    /**
784	     * Returns the existing owners in the given owner's household, i.e. those sharing its
785	     * deterministic household id (the same last name and postcode). The id is computed via
786	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
787	     * whitespace are treated as the same household. Centralising how "the same household" is matched
788	     * here keeps that definition in one place for every caller.
789	     *
790	     * @param owner the owner being created, with its household id already assigned
791	     * @return the existing owners in the owner's household (possibly empty)
792	     */
793	    private List<Owner> sameHouseholdOwners(Owner owner) {
794	        String householdId = owner.getHouseholdId();
795	        return existingOwners()
796	            .filter(existing -> householdId.equals(
797	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
798	            .toList();
799	    }
800	
801	    /**
802	     * Counts the existing owners who share the given first and last name, compared
803	     * case-insensitively. Used to fix an owner's namesake count at creation time.
804	     *
805	     * @param firstName the first name of the owner being created
806	     * @param lastName  the last name of the owner being created
807	     * @return the number of existing owners with a matching first and last name
808	     */
809	    private int countNamesakes(String firstName, String lastName) {
810	        return (int) existingOwners()
811	            .filter(existing -> existing.getFirstName() != null
812	                && existing.getFirstName().equalsIgnoreCase(firstName)
813	                && existing.getLastName() != null
814	                && existing.getLastName().equalsIgnoreCase(lastName))
815	            .count();
816	    }
817	
818	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
819	    @Override
820	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
821	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
822	        if (currentOwner == null) {
823	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
824	        }
825	        currentOwner.setAddress(ownerFieldsDto.getAddress());
826	        currentOwner.setCity(ownerFieldsDto.getCity());
827	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
828	        currentOwner.setLastName(ownerFieldsDto.getLastName());
829	        // Normalize the telephone to canonical E.164 form so it is stored and returned
830	        // consistently with create; an unformattable value is rejected with 400.
831	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
832	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
833	        this.clinicService.saveOwner(currentOwner);
834	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
835	    }
836	
837	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
838	    @Transactional
839	    @Override
840	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
841	        Owner owner = this.clinicService.findOwnerById(ownerId);
842	        if (owner == null) {
843	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
844	        }
845	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
846	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
847	        // duplicate and identity checks (see existingOwners()).
848	        owner.setDeleted(true);
849	        this.clinicService.saveOwner(owner);
850	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
851	    }
852	
853	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
854	    @Override
855	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
856	        Owner owner = this.clinicService.findOwnerById(ownerId);
857	        if (owner == null) {
858	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
859	        }
860	        HttpHeaders headers = new HttpHeaders();
861	        Pet pet = petMapper.toPet(petFieldsDto);
862	        owner.setId(ownerId);
863	        pet.setOwner(owner);
864	        pet.getType().setName(null);
865	        this.clinicService.savePet(pet);
866	        PetDto petDto = petMapper.toPetDto(pet);
867	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
868	            .buildAndExpand(pet.getId()).toUri());
869	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
870	    }
871	
872	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
873	    @Override
874	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
875	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
876	        if (currentOwner != null) {
877	            Pet currentPet = this.clinicService.findPetById(petId);
878	            if (currentPet != null) {
879	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
880	                currentPet.setName(petFieldsDto.getName());
881	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
882	                this.clinicService.savePet(currentPet);
883	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
884	            }
885	        }
886	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
887	    }
888	
889	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
890	    @Override
891	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
892	        HttpHeaders headers = new HttpHeaders();
893	        Visit visit = visitMapper.toVisit(visitFieldsDto);
894	        Pet pet = new Pet();
895	        pet.setId(petId);
896	        visit.setPet(pet);
897	        this.clinicService.saveVisit(visit);
898	        VisitDto visitDto = visitMapper.toVisitDto(visit);
899	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
900	            .buildAndExpand(visit.getId()).toUri());
901	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
902	    }
903	
904	
905	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
906	    @Override
907	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
908	        Owner owner = this.clinicService.findOwnerById(ownerId);
909	        if (owner != null) {
910	            Pet pet = owner.getPet(petId);
911	            if (pet != null) {
912	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
913	            }
914	        }
915	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
916	    }
